code_snippet:
h1 {
  font-size: clamp(1rem, 4vw, 3rem);
}
/* 뷰포트 너비: 320px, 기본 폰트: 16px */

explanation_code:
/* clamp 동작 원리 */
/* 320px: 4vw=12.8px < 1rem(16px) → 16px */
/* 500px: 4vw=20px, 범위 내 → 20px */
/* 800px: 4vw=32px > 3rem(48px)? 아니므로 32px */
/* 1200px: 4vw=48px = 3rem → 48px (최댓값) */

/* 컨테이너 설정 */
.card-wrapper {
  container-type: inline-size;
  container-name: card;
}
/* 특정 컨테이너 이름으로 쿼리 */
@container card (min-width: 300px) {
  .card-title { font-size: 1.25rem; }
}

/* 세 표현식 모두 동일한 결과 */
.box { width: clamp(300px, 90vw, 800px); }
/* 동일: */
.box { width: min(max(300px, 90vw), 800px); }

/* 컨테이너 쿼리 단위 종류 */
/* cqw: 컨테이너 너비의 1% */
/* cqh: 컨테이너 높이의 1% */
/* cqi: 컨테이너 인라인 크기의 1% */
/* cqb: 컨테이너 블록 크기의 1% */
.child { font-size: 4cqi; } /* 컨테이너 너비 500px → 20px */

/* and: 두 조건 모두 */
@media (min-width: 600px) and (orientation: landscape) { ... }
/* 쉼표(or): 하나만 만족해도 */
@media (min-width: 600px), (orientation: landscape) { ... }

/* 스크롤바 공간 확보로 레이아웃 이동 방지 */
body {
  scrollbar-gutter: stable;
}
/* 또는 */
.full-width {
  width: 100%; /* vw 대신 사용 */
}

/* 스타일 쿼리 사용 예 */
.parent { --layout: grid; }
@container style(--layout: grid) {
  .child { display: grid; }
}
@container style(--layout: flex) {
  .child { display: flex; }
}

/* CSS 네스팅 */
.parent {
  color: blue;
  .child {
    color: red; /* .parent .child */
  }
  &:hover {
    color: green; /* .parent:hover */
  }
}

/* :has() 활용 예 */
/* img가 있는 카드 */
.card:has(img) { padding: 0; }
/* 체크된 라디오 버튼의 레이블 */
label:has(input[type=radio]:checked) { font-weight: bold; }
/* 자식이 없는 요소 */
.list:not(:has(li)) { display: none; }

