/* 전체 사이트 강조 색상 설정 */
:root {
  accent-color: #6366f1;
}
/* 특정 요소만 */
input[type="range"] {
  accent-color: hotpink;
}

/* @supports 기본 사용 */
@supports (display: grid) {
  .container { display: grid; }
}
/* 미지원 시 폴백 */
@supports not (display: grid) {
  .container { display: flex; }
}
/* 선택자 지원 확인 */
@supports selector(:has(a)) {
  .parent:has(a) { color: blue; }
}

/* 전체 페이지에 다크 모드 지원 활성화 */
:root {
  color-scheme: light dark;
}
/* 특정 요소만 강제 다크 모드 */
.dark-component {
  color-scheme: dark;
}

