explanation_code:
/* dense vs sparse 비교 */
/* sparse(기본): 아이템 순서 유지, 빈 셀 허용 */
.grid { grid-auto-flow: row; }
/* dense: 빈 셀 채우기, 순서 변경 가능 */
.grid { grid-auto-flow: row dense; }
/* 마소니리 효과에 유용 */

/* z-index 충돌 방지 */
.component {
  isolation: isolate; /* 내부 z-index를 외부로부터 격리 */
}
.component .overlay {
  z-index: 999; /* 컴포넌트 내부에서만 유효 */
}

/* 실험적 마소니리 레이아웃 */
.masonry {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: masonry; /* 실험적 */
  gap: 1rem;
}

/* column-span 사용 예 */
.article {
  column-count: 3;
  column-gap: 2rem;
}
.article h2 {
  column-span: all;  /* 전체 너비 제목 */
  text-align: center;
  border-bottom: 2px solid;
}

/* 반응형 그리드 */
.grid {
  display: grid;
  /* 자동으로 컬럼 수 조정, 최소 200px */
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 1rem;
}

/* calc() 올바른 사용 */
.element {
  width: calc(100% - 40px);     /* 올바름 */
  height: calc(100vh - 80px);   /* 올바름 */
  margin: calc(1rem + 10px);    /* 올바름 */
  /* width: calc(100%-40px); */ /* 잘못됨: 공백 없음 */
}

