explanation_code:
/* CSS 카운터 구현 */
ol {
  counter-reset: item 0; /* 0부터 시작 */
  list-style: none;
  padding: 0;
}
li::before {
  counter-increment: item;
  content: counter(item) ". ";
  font-weight: bold;
}

/* 다양한 그레이디언트 */
.linear  { background: linear-gradient(45deg, red, blue); }
.radial  { background: radial-gradient(ellipse at top, red, blue); }
.conic   { background: conic-gradient(from 0deg, red, blue, red); }

/* color-mix() 활용 예 */
:root {
  --primary: #6366f1;
  --primary-light: color-mix(in srgb, var(--primary), white 30%);
  --primary-dark: color-mix(in srgb, var(--primary), black 20%);
}
/* 두 색상 혼합 */
.blend { color: color-mix(in oklch, red 70%, blue); }

/* fit-content() 동작 */
/* 콘텐츠 < 200px: 콘텐츠 크기 */
/* 콘텐츠 > 200px: 200px (최대) */
.grid {
  display: grid;
  grid-template-columns: fit-content(200px) 1fr;
}

/* calc() 곱셈/나눗셈 규칙 */
.valid {
  width: calc(10px * 10);    /* 유효: 100px */
  height: calc(100px / 4);   /* 유효: 25px */
}
/* 유효하지 않음 */
/* width: calc(10px * 10px); */  /* 무효: px² */
/* width: calc(100px / 4px); */  /* 무효 */

/* attr() 활용 예 */
/* 툴팁 구현 */
[data-tooltip]::after {
  content: attr(data-tooltip);
  /* 툴팁 스타일 */
}
/* 링크 URL 표시 (인쇄 스타일) */
@media print {
  a::after { content: " (" attr(href) ")"; }
}

/* 정확한 유체 스케일링 */
.section {
  padding: clamp(
    16px,
    calc(16px + (48 - 16) * ((100vw - 320px) / (1280 - 320))),
    48px
  );
}
/* 단순화 버전 (근사값) */
.section-simple {
  padding: clamp(1rem, 2vw + 0.5rem, 3rem);
}

/* circle vs ellipse */
.circle  { background: radial-gradient(circle, red, blue); }
.ellipse { background: radial-gradient(ellipse, red, blue); }
/* 크기 직접 지정 */
.custom  { background: radial-gradient(ellipse 80% 40% at center, red, blue); }

